const express = require('express');
const { MessageChannel } = require('worker_threads');
const crmExportWorker = require('../workers/sharedCrmWorker');
const { verifyJwtToken } = require('../auth');

const router = express.Router();

router.post('/api/crm/companies/:companyId/export-csv', verifyJwtToken, (req, res) => {
  if (req.user.companyId !== req.params.companyId && !req.user.isSuperAdmin) {
    return res.status(403).json({ error: 'Forbidden: access denied to specified company data' });
  }

  const { port1, port2 } = new MessageChannel();

  crmExportWorker.postMessage({
    task: 'GENERATE_COMPANY_CSV',
    companyId: req.params.companyId,
    clientPort: port2
  }, [port2]);

  port1.on('message', (msg) => {
    if (msg.done) {
      res.json({ exportFileId: msg.fileId, rowCount: msg.count });
    }
  });
});
